<script setup>
const{data}=await useFetch('/api/programs');const modal=ref(false);const done=ref(false);const selected=ref(null);const slot=ref('');const form=reactive({name:'',email:'',goal:''});
const programs=computed(()=>data.value?.programs||[]);const slots=computed(()=>data.value?.slots||[])
function choose(program){selected.value=program;modal.value=true;done.value=false}
async function submit(){await $fetch('/api/bookings',{method:'POST',body:{...form,programId:selected.value?.id,slot:slot.value}});done.value=true}
</script>
