<div v-if="modal" class="shade" @click="modal=false"></div><div v-if="modal" class="modal glass"><button class="x" @click="modal=false">×</button><template v-if="!done"><p class="eyebrow">DISCOVERY CALL</p><h2>Let's find your next step.</h2><p class="muted">{{selected?.name}} program · Choose a sample time.</p><label>Name<input v-model="form.name" placeholder="Your name"></label><label>Email<input v-model="form.email" type="email" placeholder="you@example.com"></label><label>Your main goal<textarea v-model="form.goal" placeholder="What would progress look like?"></textarea></label><div class="slots"><button v-for="s in slots" :key="s" :class="{active:slot===s}" @click="slot=s">{{s}}</button></div><button class="primary full" :disabled="!form.name||!form.email||!slot" @click="submit">Confirm sample booking</button></template><template v-else><div class="check">✓</div><h2>You're on the calendar.</h2><p>Sample confirmation created for {{slot}}.</p><button class="primary" @click="modal=false">Done</button></template></div></main></template>
